/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNumber = require( '@stdlib/assert/is-number' );
var isString = require( '@stdlib/assert/is-string' );
var isCollection = require( '@stdlib/assert/is-collection' );
var format = require( '@stdlib/string/format' );
var everyBy2 = require( './../../every_by2.js' );


// FUNCTIONS //

/**
* Predicate function which tests whether two elements are equal.
*
* @private
* @param {Object} v1 - first value
* @param {Object} v2 - second value
* @returns {boolean} boolean indicating whether two elements are equal
*/
function predicate( v1, v2 ) {
	return ( v1 === v2 );
}


// MAIN //

/**
* Sets the w axis tics label.
*
* @private
* @param {Array} value - Array of the labels for tics.
* @throws {TypeError} must be a array of string or number literals
*/
function set( value ) {
	var isChange;
	var data;
	var i;

	data = this._axisDataObjs[ 3 ].rawLabels;
	if ( !isCollection( value )) {
		throw new TypeError( format( 'invalid assignment. `%s` must be an array. Value: `%s`.', 'wAxisTicsLabels', value ) );
	}
	if ( !this._axisDataObjs[ 3 ].axis && data.length === value.length && everyBy2( data, value, predicate ) ) {
		isChange = false;
	}
	else {
		isChange = true;
	}
	if ( isChange ) {
		this.wAxis = true;
		data.length = value.length;
		for ( i = 0; i < value.length; i++ ) {
			if ( !isNumber( value[ i ] ) && !isString( value[ i ] ) ) {
				throw new TypeError( format( 'invalid assignment. `%s` number or string is expected. Value: `%s`.', 'wAxisTicsLabel', value ) );
			}
			data[ i ] = value[ i ];
		}
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
